import os
from typing import Any, Dict, List, Optional

import requests


PERSPECTIVE_API_URL = "https://commentanalyzer.googleapis.com/v1alpha1/comments:analyze"


def _normalize_message(item: Any) -> str:
    if isinstance(item, str):
        return item
    if isinstance(item, dict):
        for key in ("text", "message", "content", "body"):
            if key in item and item[key] is not None:
                return str(item[key])
    return str(item)


def _decision_from_scores(scores: Dict[str, Any], threshold: float) -> Dict[str, Any]:
    toxicity = 0.0
    severe_toxicity = 0.0
    insult = 0.0
    threat = 0.0
    identity_attack = 0.0
    profanity = 0.0

    for attr_name, target in (
        ("TOXICITY", "toxicity"),
        ("SEVERE_TOXICITY", "severe_toxicity"),
        ("INSULT", "insult"),
        ("THREAT", "threat"),
        ("IDENTITY_ATTACK", "identity_attack"),
        ("PROFANITY", "profanity"),
    ):
        attr = scores.get(attr_name, {})
        if isinstance(attr, dict):
            value = attr.get("summaryScore", {}).get("value", 0.0)
            try:
                value = float(value)
            except (TypeError, ValueError):
                value = 0.0
            if target == "toxicity":
                toxicity = value
            elif target == "severe_toxicity":
                severe_toxicity = value
            elif target == "insult":
                insult = value
            elif target == "threat":
                threat = value
            elif target == "identity_attack":
                identity_attack = value
            elif target == "profanity":
                profanity = value

    max_score = max(toxicity, severe_toxicity, insult, threat, identity_attack, profanity)
    decision = "reject" if max_score >= threshold else "allow"
    return {
        "decision": decision,
        "scores": {
            "toxicity": toxicity,
            "severe_toxicity": severe_toxicity,
            "insult": insult,
            "threat": threat,
            "identity_attack": identity_attack,
            "profanity": profanity,
        },
        "max_score": max_score,
    }


def moderate_batch(messages: List[Any], threshold: float = 0.5) -> List[Dict[str, Any]]:
    api_key = os.getenv("PERSPECTIVE_API_KEY")
    if not api_key:
        raise EnvironmentError("PERSPECTIVE_API_KEY is required")

    requested_attributes = {
        "TOXICITY": {},
        "SEVERE_TOXICITY": {},
        "INSULT": {},
        "THREAT": {},
        "IDENTITY_ATTACK": {},
        "PROFANITY": {},
    }

    results: List[Dict[str, Any]] = []
    for idx, item in enumerate(messages):
        text = _normalize_message(item)
        payload = {
            "comment": {"text": text},
            "requestedAttributes": requested_attributes,
            "doNotStore": True,
            "languages": ["en"],
        }
        url = f"{PERSPECTIVE_API_URL}?key={api_key}"
        try:
            response = requests.post(url, json=payload, timeout=30)
            response.raise_for_status()
            data = response.json()
            attr_scores = data.get("attributeScores", {})
            decision_data = _decision_from_scores(attr_scores, threshold)
            results.append(
                {
                    "index": idx,
                    "message": text,
                    "decision": decision_data["decision"],
                    "scores": decision_data["scores"],
                    "max_score": decision_data["max_score"],
                    "provider_response": data,
                }
            )
        except Exception as exc:
            results.append(
                {
                    "index": idx,
                    "message": text,
                    "decision": "error",
                    "error": str(exc),
                }
            )
    return results
